INSERT INTO `wf_process_definition` VALUES (13, 'BUDGET_APPLY', '预算申请', 'BUDGET', 'APPLY', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<bpmn2:definitions xmlns:bpmn2=\"http://www.omg.org/spec/BPMN/20100524/MODEL\" xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\" xmlns:dc=\"http://www.omg.org/spec/DD/20100524/DC\" xmlns:di=\"http://www.omg.org/spec/DD/20100524/DI\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" id=\"sample-diagram\" targetNamespace=\"http://bpmn.io/schema/bpmn\">\n  <bpmn2:process id=\"Process_1\" isExecutable=\"true\">\n    <bpmn2:startEvent id=\"StartEvent_1\" name=\"开始\" description=\"\">\n      <bpmn2:outgoing>Flow_0l2to68</bpmn2:outgoing>\n    </bpmn2:startEvent>\n    <bpmn2:sequenceFlow id=\"Flow_0l2to68\" sourceRef=\"StartEvent_1\" targetRef=\"Activity_0u62iux\" />\n    <bpmn2:userTask id=\"Activity_0u62iux\" name=\"提交\" approvalType=\"SINGLE\" assigneeType=\"initiator\" assigneeId=\"null\" assigneeName=\"\" positionCode=\"\" deptCode=\"\" multiInstanceType=\"ALL\" multiInstanceCount=\"0\" completionCondition=\"100\" allowAddsign=\"0\" allowReduceSign=\"0\" allowTransfer=\"0\" allowReject=\"0\" rejectStrategy=\"PREVIOUS\" needPrint=\"1\" printOrder=\"1\" enableTimeout=\"0\" timeoutHours=\"24\" timeoutAction=\"NOTIFY\" description=\"\" assigneeCode=\"\" responsibleType=\"\">\n      <bpmn2:incoming>Flow_0l2to68</bpmn2:incoming>\n      <bpmn2:outgoing>Flow_0uozrlo</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:sequenceFlow id=\"Flow_0uozrlo\" sourceRef=\"Activity_0u62iux\" targetRef=\"Activity_0rjti7m\" />\n    <bpmn2:userTask id=\"Activity_0rjti7m\" name=\"部门初审\" approvalType=\"SINGLE\" assigneeType=\"user\" assigneeId=\"null\" assigneeName=\"\" positionCode=\"\" deptCode=\"\" multiInstanceType=\"ALL\" multiInstanceCount=\"0\" completionCondition=\"100\" allowAddsign=\"1\" allowReduceSign=\"0\" allowTransfer=\"1\" allowReject=\"1\" rejectStrategy=\"SPECIFY\" needPrint=\"1\" printOrder=\"2\" enableTimeout=\"0\" timeoutHours=\"24\" timeoutAction=\"NOTIFY\" description=\"\">\n      <bpmn2:incoming>Flow_0uozrlo</bpmn2:incoming>\n      <bpmn2:outgoing>Flow_0spry7l</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:sequenceFlow id=\"Flow_0spry7l\" sourceRef=\"Activity_0rjti7m\" targetRef=\"Activity_1yo2ygw\" />\n    <bpmn2:userTask id=\"Activity_1yo2ygw\" name=\"归口部门审核\">\n      <bpmn2:incoming>Flow_0spry7l</bpmn2:incoming>\n      <bpmn2:outgoing>Flow_19dvser</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:sequenceFlow id=\"Flow_19dvser\" sourceRef=\"Activity_1yo2ygw\" targetRef=\"Activity_14kuaww\" />\n    <bpmn2:userTask id=\"Activity_14kuaww\" name=\"财务部门审核\">\n      <bpmn2:incoming>Flow_19dvser</bpmn2:incoming>\n      <bpmn2:outgoing>Flow_16f3wdu</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:sequenceFlow id=\"Flow_16f3wdu\" sourceRef=\"Activity_14kuaww\" targetRef=\"Activity_0kgxn2r\" />\n    <bpmn2:userTask id=\"Activity_0kgxn2r\" name=\"分管院领导\">\n      <bpmn2:incoming>Flow_16f3wdu</bpmn2:incoming>\n      <bpmn2:outgoing>Flow_0rxmupb</bpmn2:outgoing>\n      <bpmn2:outgoing>Flow_1cykmhv</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:endEvent id=\"Event_1au3v53\" name=\"结束\">\n      <bpmn2:incoming>Flow_0rxmupb</bpmn2:incoming>\n      <bpmn2:incoming>Flow_1yyqwl8</bpmn2:incoming>\n    </bpmn2:endEvent>\n    <bpmn2:sequenceFlow id=\"Flow_0rxmupb\" name=\"小于五万\" sourceRef=\"Activity_0kgxn2r\" targetRef=\"Event_1au3v53\">\n      <bpmn2:conditionExpression xsi:type=\"bpmn2:tFormalExpression\">${budget_apply.apply_amount&lt;50000}</bpmn2:conditionExpression>\n    </bpmn2:sequenceFlow>\n    <bpmn2:sequenceFlow id=\"Flow_1cykmhv\" name=\"大于五万\" sourceRef=\"Activity_0kgxn2r\" targetRef=\"Activity_0952cwb\">\n      <bpmn2:conditionExpression xsi:type=\"bpmn2:tFormalExpression\">${budget_apply.apply_amount&gt;=50000}</bpmn2:conditionExpression>\n    </bpmn2:sequenceFlow>\n    <bpmn2:userTask id=\"Activity_0952cwb\" name=\"院长\">\n      <bpmn2:incoming>Flow_1cykmhv</bpmn2:incoming>