PMNShape>\n      <bpmndi:BPMNShape id=\"Activity_11j9or9_di\" bpmnElement=\"Activity_0952cwb\">\n        <dc:Bounds x=\"570\" y=\"230\" width=\"100\" height=\"80\" />\n        <bpmndi:BPMNLabel />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNEdge id=\"Flow_0l2to68_di\" bpmnElement=\"Flow_0l2to68\">\n        <di:waypoint x=\"215\" y=\"117\" />\n        <di:waypoint x=\"270\" y=\"117\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_0uozrlo_di\" bpmnElement=\"Flow_0uozrlo\">\n        <di:waypoint x=\"320\" y=\"157\" />\n        <di:waypoint x=\"320\" y=\"210\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_0spry7l_di\" bpmnElement=\"Flow_0spry7l\">\n        <di:waypoint x=\"370\" y=\"250\" />\n        <di:waypoint x=\"420\" y=\"250\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_19dvser_di\" bpmnElement=\"Flow_19dvser\">\n        <di:waypoint x=\"470\" y=\"210\" />\n        <di:waypoint x=\"470\" y=\"157\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_16f3wdu_di\" bpmnElement=\"Flow_16f3wdu\">\n        <di:waypoint x=\"520\" y=\"117\" />\n        <di:waypoint x=\"570\" y=\"117\" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_0rxmupb_di\" bpmnElement=\"Flow_0rxmupb\">\n        <di:waypoint x=\"670\" y=\"117\" />\n        <di:waypoint x=\"832\" y=\"117\" />\n        <bpmndi:BPMNLabel>\n          <dc:Bounds x=\"729\" y=\"99\" width=\"45\" height=\"14\" />\n        </bpmndi:BPMNLabel>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_1cykmhv_di\" bpmnElement=\"Flow_1cykmhv\">\n        <di:waypoint x=\"620\" y=\"157\" />\n        <di:waypoint x=\"620\" y=\"230\" />\n        <bpmndi:BPMNLabel>\n          <dc:Bounds x=\"613\" y=\"191\" width=\"45\" height=\"14\" />\n        </bpmndi:BPMNLabel>\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id=\"Flow_1yyqwl8_di\" bpmnElement=\"Flow_1yyqwl8\">\n        <di:waypoint x=\"670\" y=\"270\" />\n        <di:waypoint x=\"850\" y=\"270\" />\n        <di:waypoint x=\"850\" y=\"135\" />\n      </bpmndi:BPMNEdge>\n    </bpmndi:BPMNPlane>\n  </bpmndi:BPMNDiagram>\n</bpmn2:definitions>\n', '{\"customProperties\":{\"Activity_0u62iux\":{\"approvalType\":\"SINGLE\",\"assigneeType\":\"initiator\",\"multiInstanceType\":\"ALL\",\"multiInstanceCount\":0,\"completionCondition\":100,\"allowAddsign\":0,\"allowReduceSign\":0,\"allowTransfer\":0,\"allowReject\":0,\"rejectStrategy\":\"PREVIOUS\",\"needPrint\":1,\"printOrder\":1,\"enableTimeout\":0,\"timeoutHours\":24,\"timeoutAction\":\"NOTIFY\"},\"Activity_0rjti7m\":{\"approvalType\":\"SINGLE\",\"assigneeType\":\"responsible\",\"deptCode\":\"DEPT_MANAGER\",\"responsibleType\":\"DEPT_MANAGER\",\"multiInstanceType\":\"ALL\",\"multiInstanceCount\":0,\"completionCondition\":100,\"allowAddsign\":1,\"allowReduceSign\":0,\"allowTransfer\":1,\"allowReject\":1,\"rejectStrategy\":\"SPECIFY\",\"needPrint\":1,\"printOrder\":2,\"enableTimeout\":0,\"timeoutHours\":24,\"timeoutAction\":\"NOTIFY\"},\"Activity_1yo2ygw\":{\"approvalType\":\"SINGLE\",\"assigneeType\":\"manage_dept\",\"multiInstanceType\":\"ALL\",\"multiInstanceCount\":2,\"completionCondition\":100,\"allowAddsign\":1,\"allowReduceSign\":0,\"allowTransfer\":1,\"allowReject\":1,\"rejectStrategy\":\"SPECIFY\",\"needPrint\":1,\"printOrder\":3,\"enableTimeout\":0,\"timeoutHours\":24,\"timeoutAction\":\"NOTIFY\"},\"Activity_14kuaww\":{\"approvalType\":\"OR\",\"assigneeType\":\"position\",\"positionCode\":\"GW001\",\"multiInstanceType\":\"ALL\",\"multiInstanceCount\":0,\"completionCondition\":100,\"allowAddsign\":1,\"allowReduceSign\":0,\"allowTransfer\":1,\"allowReject\":1,\"rejectStrategy\":\"SPECIFY\",\"needPrint\":1,\"printOrder\":4,\"enableTimeout\":0,\"timeoutHours\":24,\"timeoutAction\":\"NOTIFY\"},\"Activity_0kgxn2r\":{\"approvalType\":\"SINGLE\",\"assigneeType\":\"responsible\",\"deptCode\":\"VICE_PRESIDENT\",\"responsibleType\":\"VICE_PRESIDENT\",\"multiInstanceType\":\"ALL\",\"multiInstanceCount\":0,\"completionCondition\":100,\"allowAddsign\":1,\"allowReduceSign\":0,\"allowTransfer\":1,\"allowReject\":1,\"rejectStrategy\":\"SPECIFY\",\"needPrint\":1,\"printOrder\":5,\"enableTimeout\":0,\"timeoutHours\":24,\"timeoutAction\":\"NOTIFY\"},\"Activity_0952cwb\":{\"approvalType\":\"SINGLE\",\"assigneeType\":\"user\",\"assigneeId\":452,\"assigneeName\":\"张三\",\"assigneeCode\":\"001001\",\"multiInstanceType\":\"ALL\",\"multiInstanceCount\":0,\"completionCondition\":100,\"allowAddsign\":1,\"allowReduceSign\":0,\"allowTransfer\":1,\"allowReject\":1,\"rejectStrategy\":\"SPECIFY\",\"needPrint\":1,\"printOrder\":6,\"enableTimeout\":0,\"timeoutHours\":24,\"timeoutAction\":\"NOTIFY\"},\"Flow_0rxmupb\":{\"conditionType\":\"expression\",\"conditionExpression\":\"${budget_apply.apply_amount<50000}\"},\"Flow_1cykmhv\":{\"conditionType\":\"expression\",\"conditionExpression\":\"${budget_apply.apply_amount>=50000}\"},\"Flow_1yyqwl8\":{\"conditionType\":\"none\"}}}', 1, 1, '', 'admin', '2025-12-21 19:55:27', '2026-01-01 11:23:48');
INSERT INTO `wf_process_definition` VALUES (14, 'APPLY_MEAL', '申请餐费', 'APPLY', 'MEAL', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<bpmn2:definitions xmlns:bpmn2=\"http://www.omg.org/spec/BPMN/20100524/MODEL\" xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\" xmlns:dc=\"http://www.omg.org/spec/DD/20100524/DC\" xmlns:di=\"http://www.omg.org/spec/DD/20100524/DI\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" id=\"sample-diagram\" targetNamespace=\"http://bpmn.io/schema/bpmn\">\n  <bpmn2:process id=\"Process_1\" isExecutable=\"true\">\n    <bpmn2:startEvent id=\"StartEvent_1\" name=\"开始\">\n      <bpmn2:outgoing>Flow_1unlr17</bpmn2:outgoing>\n    </bpmn2:startEvent>\n    <bpmn2:userTask id=\"Activity_0b4zowc\" name=\"科主任审核\">\n      <bpmn2:incoming>Flow_1j19in4</bpmn2:incoming>\n      <bpmn2:outgoing>Flow_0jkr987</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:userTask id=\"Activity_0873wj8\" name=\"护士长审核\">\n      <bpmn2:incoming>Flow_0uuehig</bpmn2:incoming>\n      <bpmn2:outgoing>Flow_0qj8vf9</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:sequenceFlow id=\"Flow_0jkr987\" sourceRef=\"Activity_0b4zowc\" targetRef=\"Activity_1feci1m\" />\n    <bpmn2:sequenceFlow id=\"Flow_0qj8vf9\" name=\"\" sourceRef=\"Activity_0873wj8\" targetRef=\"Activity_1feci1m\" />\n    <bpmn2:userTask id=\"Activity_1feci1m\" name=\"财务审核\">\n      <bpmn2:incoming>Flow_0jkr987</bpmn2:incoming>\n      <bpmn2:incoming>Flow_0qj8vf9</bpmn2:incoming>\n      <bpmn2:outgoing>Flow_1ll82gf</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:sequenceFlow id=\"Flow_1ll82gf\" sourceRef=\"Activity_1feci1m\" targetRef=\"Activity_0vvi6qk\" />\n    <bpmn2:userTask id=\"Activity_0vvi6qk\" name=\"院领导审核\">\n      <bpmn2:incoming>Flow_1ll82gf</bpmn2:incoming>\n      <bpmn2:outgoing>Flow_19jy3he</bpmn2:outgoing>\n      <bpmn2:outgoing>Flow_10ndagq</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:sequenceFlow id=\"Flow_1unlr17\" sourceRef=\"StartEvent_1\" targetRef=\"Activity_0nb50gh\" />\n    <bpmn2:sequenceFlow id=\"Flow_1j19in4\" name=\"非护士\" sourceRef=\"Activity_0nb50gh\" targetRef=\"Activity_0b4zowc\">\n      <bpmn2:conditionExpression xsi:type=\"bpmn2:tFormalExpression\">${ctrl_payout.is_nurse==0}</bpmn2:conditionExpression>\n    </bpmn2:sequenceFlow>\n    <bpmn2:sequenceFlow id=\"Flow_0uuehig\" name=\"护士\" sourceRef=\"Activity_0nb50gh\" targetRef=\"Activity_0873wj8\">\n      <bpmn2:conditionExpression xsi:type=\"bpmn2:tFormalExpression\">${ctrl_payout.is_nurse==1}</bpmn2:conditionExpression>\n    </bpmn2:sequenceFlow>\n    <bpmn2:userTask id=\"Activity_0nb50gh\" name=\"提交\">\n      <bpmn2:incoming>Flow_1unlr17</bpmn2:incoming>\n      <bpmn2:outgoing>Flow_1j19in4</bpmn2:outgoing>\n      <bpmn2:outgoing>Flow_0uuehig</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:sequenceFlow id=\"Flow_19jy3he\" name=\"&#62;=五万\" sourceRef=\"Activity_0vvi6qk\" targetRef=\"Activity_0wmkx5a\">\n      <bpmn2:conditionExpression xsi:type=\"bpmn2:tFormalExpression\">${ctrl_payout.apply_amount&gt;=50000}</bpmn2:conditionExpression>\n    </bpmn2:sequenceFlow>\n    <bpmn2:userTask id=\"Activity_0wmkx5a\" name=\"院长\">\n      <bpmn2:incoming>Flow_19jy3he</bpmn2:incoming>\n      <bpmn2:outgoing>Flow_1abnuwt</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:endEvent id=\"Event_1l9lxlb\" name=\"结束\">\n      <bpmn2:incoming>Flow_10ndagq</bpmn2:incoming>\n      <bpmn2:incoming>Flow_1abnuwt</bpmn2:incoming>\n    </bpmn2:endEvent>\n    <bpmn2:sequenceFlow id=\"Flow_10ndagq\" name=\"&#60;五万\" sourceRef=\"Activity_0vvi6qk\" targetRef=\"Event_1l9lxlb\">\n      <bpmn2:conditionExpression xsi:type=\"bpmn2:tFormalExpression\">${ctrl_payout.apply_amount&lt;50000}</bpmn2:conditionExpression>\n    </bpmn2:sequenceFlow>\n    <bpmn2:sequenceFlow id=\"Flow_1abnuwt\" sourceRef=\"Activity_0wmkx5a\" targetRef=\"Event_1l9lxlb\" />\n  </bpmn2:process>\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_1\">\n    <bpmndi:BPMNPlane id=\"BPMNPlane_1\" bpmnElement=\"Process_1\">\n      <bpmndi:BPMNShape