-- ----------------------------
-- Table structure for asset_account
-- ----------------------------
DROP TABLE IF EXISTS `asset_account`;
CREATE TABLE `asset_account`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `asset_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资产编码（唯一）',
  `asset_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资产名称',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '规格型号',
  `unit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '单位（台/套/个等）',
  `stock_num` int NOT NULL DEFAULT 0 COMMENT '当前库存数量（领用后自动扣减）',
  `price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '单价（元）',
  `manufacturer` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '生产厂家',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_asset_code`(`asset_code` ASC) USING BTREE COMMENT '资产编码唯一索引',
  INDEX `idx_stock_num`(`stock_num` ASC) USING BTREE COMMENT '库存数量索引'
) ENGINE = InnoDB AUTO_INCREMENT = 414 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '资产台账表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of asset_account
-- ----------------------------

-- ----------------------------
-- Table structure for asset_category
-- ----------------------------
DROP TABLE IF EXISTS `asset_category`;
CREATE TABLE `asset_category`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键（分类唯一ID）',
  `category_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分类编码（唯一）',
  `category_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分类名称',
  `parent_id` bigint NULL DEFAULT 0 COMMENT '父级分类ID：0=一级分类，非0=关联父级ID',
  `level` tinyint NOT NULL COMMENT '分类层级：1=一级 2=二级 3=三级',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：1=启用 0=禁用',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_category_code`(`category_code` ASC) USING BTREE COMMENT '分类编码唯一',
  INDEX `idx_parent_id`(`parent_id` ASC) USING BTREE COMMENT '父级分类索引（三级联动查询）',
  INDEX `idx_level`(`level` ASC) USING BTREE COMMENT '层级索引（筛选一级/二级分类）'
) ENGINE = InnoDB AUTO_INCREMENT = 115 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '资产分类表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of asset_category
-- ----------------------------

-- ----------------------------
-- Table structure for asset_in_storage
-- ----------------------------
DROP TABLE IF EXISTS `asset_in_storage`;
CREATE TABLE `asset_in_storage`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '入库ID',
  `storage_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '入库单号（RKD年月日0001）',
  `purchase_id` bigint NULL DEFAULT NULL COMMENT '采购ID（关联 asset_purchase.id，完成采购时生成入库单）',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '采购单号（关联 asset_purchase.order_no，冗余字段）',
  `apply_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请单号（关联 asset_purchase_apply_main.apply_no，冗余字段）',
  `storage_date` date NULL DEFAULT NULL COMMENT '入库日期',
  `storage_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'NOT_STORED' COMMENT '入库状态（从 sys_code 的 IN_STORAGE_STATUS 获取）：NOT_STORED-未入库，STORED-已入库',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作人姓名',
  `total_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '入库总金额',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `storage_no`(`storage_no` ASC) USING BTREE,
  INDEX `idx_storage_no`(`storage_no` ASC) USING BTREE,
  INDEX `idx_purchase_id`(`purchase_id` ASC) USING BTREE,
  INDEX `idx_order_no`(`order_no` ASC) USING BTREE,
  INDEX `idx_apply_no`(`apply_no` ASC) USING BTREE,
  INDEX `idx_storage_status`(`storage_status` ASC) USING BTREE,
  INDEX `idx_storage_date`(`storage_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '入库主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of asset_in_storage
-- ----------------------------

-- ----------------------------
-- Table structure for asset_in_storage_detail
-- ----------------------------
DROP TABLE IF EXISTS `asset_in_storage_detail`;
CREATE TABLE `asset_in_storage_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `storage_id` bigint NOT NULL COMMENT '入库ID（关联 asset_in_storage.id）',
  `storage_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '入库单号（冗余字段，方便查询）',
  `purchase_detail_id` bigint NULL DEFAULT NULL COMMENT '采购明细ID（关联 asset_purchase_detail.id）',
  `asset_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资产编码',
  `asset_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '资产名称',
  `spec` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '规格型号',
  `manufacturer` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '生产厂家',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单位',
  `storage_quantity` int NULL DEFAULT 0 COMMENT '入库数量（从采购明细导入）',
  `price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '单价',
  `total_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '总价（入库数量 * 单价）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_storage_id`(`storage_id` ASC) USING BTREE,
  INDEX `idx_storage_no`(`storage_no` ASC) USING BTREE,
  INDEX `idx_purchase_detail_id`(`purchase_detail_id` ASC) USING BTREE,
  INDEX `idx_asset_code`(`asset_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '入库明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of asset_in_storage_detail
-- ----------------------------

-- ----------------------------
-- Table structure for asset_item
-- ----------------------------
DROP TABLE IF EXISTS `asset_item`;
CREATE TABLE `asset_item`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键（规格型号唯一ID）',
  `asset_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资产编码',
  `category_id` bigint NOT NULL COMMENT '关联分类表ID（如台式电脑分类的ID）',
  `asset_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资产名称（如“联想扬天M4000q”）',
  `spec` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '详细配置规格（如“i5-13400/16G/512G SSD/Win11”）',
  `manufacturer` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '生产厂家（如“联想集团”）',
  `unit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '计量单位（台/套/个/瓶）',
  `price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '参考单价（元）',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：1=启用 0=禁用',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_item_code`(`asset_code` ASC) USING BTREE COMMENT '规格型号编码唯一',
  INDEX `idx_category_id`(`category_id` ASC) USING BTREE COMMENT '分类ID索引（查询某分类下的所有型号）',
  INDEX `idx_manufacturer`(`manufacturer` ASC) USING BTREE COMMENT '厂家索引（筛选某厂家的型号）'
) ENGINE = InnoDB AUTO_INCREMENT = 2040 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '资产规格型号表（具体分类下的型号/配置）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of asset_item
-- ----------------------------

-- ----------------------------
-- Table structure for asset_purchase
-- ----------------------------
DROP TABLE IF EXISTS `asset_purchase`;
CREATE TABLE `asset_purchase`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '采购ID',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '采购单号（ZCCG年月日0001）',
  `apply_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请单号（关联 asset_purchase_apply_main.apply_no）',
  `apply_id` bigint NULL DEFAULT NULL COMMENT '申请ID（关联 asset_purchase_apply_main.id）',
  `purchase_date` date NULL DEFAULT NULL COMMENT '采购日期',
  `purchase_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'PURCHASING' COMMENT '采购状态（从 sys_code 的 PURCHASE_STATUS 获取）：PURCHASING-采购中，COMPLETED-已完成，CANCELLED-已取消',
  `contract_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '合同编号（关联 pact_main.contract_no，完成采购时必填，且合同类型必须是采购合同）',
  `supplier_id` bigint NULL DEFAULT NULL COMMENT '供应商ID',
  `supplier_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `total_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '采购总金额',
  `operator_id` bigint NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作人姓名',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `order_no`(`order_no` ASC) USING BTREE,
  INDEX `idx_order_no`(`order_no` ASC) USING BTREE,
  INDEX `idx_apply_no`(`apply_no` ASC) USING BTREE,
  INDEX `idx_apply_id`(`apply_id` ASC) USING BTREE,
  INDEX `idx_contract_no`(`contract_no` ASC) USING BTREE,
  INDEX `idx_purchase_status`(`purchase_status` ASC) USING BTREE,
  INDEX `idx_purchase_date`(`purchase_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '采购主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of asset_purchase
-- ----------------------------

-- ----------------------------
-- Table structure for asset_purchase_apply_detail
-- ----------------------------
DROP TABLE IF EXISTS `asset_purchase_apply_detail`;
CREATE TABLE `asset_purchase_apply_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `apply_id` bigint NOT NULL COMMENT '关联主表asset_purchase_apply_main.id',
  `asset_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资产编码',
  `asset_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资产名称',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '规格型号',
  `manufacturer` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '生产厂家（如“联想集团”）',
  `unit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '单位（台/套/个等）',
  `apply_quantity` int NOT NULL COMMENT '申请数量',
  `price` decimal(10, 2) NOT NULL COMMENT '单价（元）',
  `total_price` decimal(12, 2) NOT NULL COMMENT '总价（数量×单价）',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_apply_id`(`apply_id` ASC) USING BTREE COMMENT '核心关联字段，主表ID'
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '采购申请明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of asset_purchase_apply_detail
-- ----------------------------

-- ----------------------------
-- Table structure for asset_purchase_apply_main
-- ----------------------------
DROP TABLE IF EXISTS `asset_purchase_apply_main`;
CREATE TABLE `asset_purchase_apply_main`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `apply_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '采购申请单号',
  `apply_dept_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请部门(sys_dept.dept_id)',
  `apply_emp_id` bigint NOT NULL COMMENT '申请人ID（关联sys_emp.emp_id）',
  `apply_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
  `demand_date` date NOT NULL COMMENT '需求到位日期',
  `apply_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请总原因',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态：DRAFT-草稿，PENDING-待审批，APPROVED-已审批，REJECTED-已拒绝，WITHDRAWN-已撤回（关联sys_code的APPLY_STATUS）',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `template_config_id` bigint NULL DEFAULT NULL COMMENT '模板设置id',
  `main_attach_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '附件ID',
  `apply_money` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '申请总金额',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_apply_no`(`apply_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '采购申请主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of asset_purchase_apply_main
-- ----------------------------

-- ----------------------------
-- Table structure for asset_purchase_detail
-- ----------------------------
DROP TABLE IF EXISTS `asset_purchase_detail`;
CREATE TABLE `asset_purchase_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `purchase_id` bigint NOT NULL COMMENT '采购ID（关联 asset_purchase.id）',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '采购单号（冗余字段，方便查询）',
  `apply_detail_id` bigint NULL DEFAULT NULL COMMENT '申请明细ID（关联 asset_purchase_apply_detail.id）',
  `asset_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资产编码',
  `asset_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '资产名称',
  `spec` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '规格型号',
  `manufacturer` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '生产厂家',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单位',
  `apply_quantity` int NULL DEFAULT 0 COMMENT '申请数量（从申请单明细导入）',
  `purchase_quantity` int NULL DEFAULT 0 COMMENT '采购数量',
  `price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '单价',
  `total_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '总价（采购数量 * 单价）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_purchase_id`(`purchase_id` ASC) USING BTREE,
  INDEX `idx_order_no`(`order_no` ASC) USING BTREE,
  INDEX `idx_apply_detail_id`(`apply_detail_id` ASC) USING BTREE,
  INDEX `idx_asset_code`(`asset_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '采购明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of asset_purchase_detail
-- ----------------------------

-- ----------------------------
-- Table structure for asset_receive_detail
-- ----------------------------
DROP TABLE IF EXISTS `asset_receive_detail`;
CREATE TABLE `asset_receive_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `receive_id` bigint NOT NULL COMMENT '领用ID（关联 asset_receive_main.id）',
  `receive_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '领用单号（冗余字段，方便查询）',
  `asset_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资产编码',
  `asset_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '资产名称',
  `spec` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '规格型号',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单位',
  `receive_num` int NULL DEFAULT 0 COMMENT '领用数量',
  `manufacturer` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '生产厂家',
  `remain_num` int NULL DEFAULT NULL COMMENT '剩余库存数量（领用后的库存数量）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_receive_id`(`receive_id` ASC) USING BTREE,
  INDEX `idx_receive_no`(`receive_no` ASC) USING BTREE,
  INDEX `idx_asset_code`(`asset_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '资产领用明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of asset_receive_detail
-- ----------------------------

-- ----------------------------
-- Table structure for asset_receive_main
-- ----------------------------
DROP TABLE IF EXISTS `asset_receive_main`;
CREATE TABLE `asset_receive_main`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `receive_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '领用单号',
  `apply_emp_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请人ID（关联sys_emp表）',
  `dept_id` bigint NOT NULL COMMENT '领用部门ID（关联部门表）',
  `receive_date` date NOT NULL COMMENT '领用日期',
  `receive_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '领用原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `operator_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '创建人emp_code（关联系统sys_emp表的emp_code）',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_receive_no`(`receive_no` ASC) USING BTREE COMMENT '领用单号唯一索引',
  INDEX `idx_dept_id`(`dept_id` ASC) USING BTREE COMMENT '部门ID索引',
  INDEX `idx_apply_emp_id`(`apply_emp_id` ASC) USING BTREE COMMENT '申请人ID索引',
  INDEX `idx_receive_date`(`receive_date` ASC) USING BTREE COMMENT '领用日期索引'
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '资产领用主记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of asset_receive_main
-- ----------------------------

-- ----------------------------
-- Table structure for attendance
-- ----------------------------
DROP TABLE IF EXISTS `attendance`;
CREATE TABLE `attendance`  (
  `attendance_id` bigint NOT NULL AUTO_INCREMENT COMMENT '考勤ID',
  `emp_id` bigint NOT NULL COMMENT '职工ID',
  `emp_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '工号',
  `emp_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '姓名',
  `attendance_date` date NOT NULL COMMENT '考勤日期',
  `check_in_time` datetime NULL DEFAULT NULL COMMENT '上班打卡时间',
  `check_out_time` datetime NULL DEFAULT NULL COMMENT '下班打卡时间',
  `work_hours` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '工作时长（小时）',
  `attendance_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'NORMAL' COMMENT '考勤状态：NORMAL-正常，LATE-迟到，EARLY_LEAVE-早退，ABSENT-缺勤，LEAVE-请假',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`attendance_id`) USING BTREE,
  UNIQUE INDEX `uk_emp_date`(`emp_id` ASC, `attendance_date` ASC) USING BTREE,
  INDEX `idx_emp_id`(`emp_id` ASC) USING BTREE,
  INDEX `idx_attendance_date`(`attendance_date` ASC) USING BTREE,
  INDEX `idx_attendance_status`(`attendance_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '考勤表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of attendance
-- ----------------------------

-- ----------------------------
-- Table structure for budget
-- ----------------------------
DROP TABLE IF EXISTS `budget`;
CREATE TABLE `budget`  (
  `budget_id` bigint NOT NULL AUTO_INCREMENT COMMENT '预算ID',
  `budget_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预算编号',
  `budget_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预算名称',
  `budget_year` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预算年度',
  `budget_period` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'YEAR' COMMENT '预算周期：YEAR-年度，QUARTER-季度，MONTH-月度',
  `subject_id` bigint NOT NULL COMMENT '预算主体ID',
  `subject_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算主体编码',
  `item_id` bigint NOT NULL COMMENT '预算项目ID',
  `item_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算项目编码',
  `budget_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '预算金额',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`budget_id`) USING BTREE,
  UNIQUE INDEX `budget_no`(`budget_no` ASC) USING BTREE,
  INDEX `idx_budget_no`(`budget_no` ASC) USING BTREE,
  INDEX `idx_budget_year`(`budget_year` ASC) USING BTREE,
  INDEX `idx_subject_id`(`subject_id` ASC) USING BTREE,
  INDEX `idx_item_id`(`item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预算表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of budget
-- ----------------------------

-- ----------------------------
-- Table structure for budget_adjustment
-- ----------------------------
DROP TABLE IF EXISTS `budget_adjustment`;
CREATE TABLE `budget_adjustment`  (
  `adjustment_id` bigint NOT NULL AUTO_INCREMENT COMMENT '调整ID',
  `adjustment_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '调整单号',
  `adjustment_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '调整类型：QUOTA_INCREASE-额度调增，QUOTA_DECREASE-额度调减，APPLY_OFFSET-申请冲销，PAYOUT_OFFSET-报账冲销',
  `related_bill_id` bigint NULL DEFAULT NULL COMMENT '关联单据ID（申请单或报账单ID）',
  `related_bill_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联单据号（申请单号或报账单号）',
  `related_bill_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联单据类型：APPLY-申请单，PAYOUT-报账单',
  `budget_id` bigint NOT NULL COMMENT '预算ID',
  `budget_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算编号',
  `subject_id` bigint NULL DEFAULT NULL COMMENT '预算主体ID',
  `item_id` bigint NULL DEFAULT NULL COMMENT '预算项目ID',
  `original_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '原预算金额',
  `adjustment_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '调整金额（正数为增加，负数为减少）',
  `adjusted_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '调整后金额',
  `adjustment_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '调整原因',
  `applicant_id` bigint NULL DEFAULT NULL COMMENT '申请人ID',
  `applicant_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人姓名',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`adjustment_id`) USING BTREE,
  UNIQUE INDEX `adjustment_no`(`adjustment_no` ASC) USING BTREE,
  INDEX `idx_adjustment_no`(`adjustment_no` ASC) USING BTREE,
  INDEX `idx_budget_id`(`budget_id` ASC) USING BTREE,
  INDEX `idx_adjustment_type`(`adjustment_type` ASC) USING BTREE,
  INDEX `idx_related_bill`(`related_bill_type` ASC, `related_bill_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预算调整表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of budget_adjustment
-- ----------------------------

-- ----------------------------
-- Table structure for budget_apply
-- ----------------------------
DROP TABLE IF EXISTS `budget_apply`;
CREATE TABLE `budget_apply`  (
  `apply_id` bigint NOT NULL AUTO_INCREMENT COMMENT '申请ID',
  `apply_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请单号',
  `budget_year` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预算年度',
  `item_id` bigint NOT NULL COMMENT '预算项目ID',
  `item_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算项目编码',
  `item_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算项目名称',
  `subject_id` bigint NULL DEFAULT NULL COMMENT '预算主体ID',
  `subject_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算主体编码',
  `subject_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算主体名称',
  `apply_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '申请金额',
  `apply_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请事由',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'DRAFT' COMMENT '状态：DRAFT-草稿，PENDING-待审批，APPROVED-已审批，REJECTED-已拒绝',
  `process_definition_id` bigint NULL DEFAULT NULL COMMENT '流程定义ID',
  `process_instance_id` bigint NULL DEFAULT NULL COMMENT '流程实例ID',
  `applicant_id` bigint NULL DEFAULT NULL COMMENT '申请人ID',
  `applicant_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人工号',
  `applicant_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人姓名',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '申请人部门ID',
  `dept_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人部门编码',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人部门名称',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `template_config_id` bigint NULL DEFAULT NULL COMMENT '模板配置ID',
  `main_attach_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '主附件ID（时间戳，用于附件关联和文件夹命名）',
  `apply_date` datetime NULL DEFAULT NULL COMMENT '申请时间',
  `applicant_phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  PRIMARY KEY (`apply_id`) USING BTREE,
  UNIQUE INDEX `apply_no`(`apply_no` ASC) USING BTREE,
  INDEX `idx_apply_no`(`apply_no` ASC) USING BTREE,
  INDEX `idx_budget_year`(`budget_year` ASC) USING BTREE,
  INDEX `idx_item_id`(`item_id` ASC) USING BTREE,
  INDEX `idx_subject_id`(`subject_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_process_instance_id`(`process_instance_id` ASC) USING BTREE,
  INDEX `idx_template_config_id`(`template_config_id` ASC) USING BTREE,
  INDEX `idx_apply_date`(`apply_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预算申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of budget_apply
-- ----------------------------

-- ----------------------------
-- Table structure for budget_category
-- ----------------------------
DROP TABLE IF EXISTS `budget_category`;
CREATE TABLE `budget_category`  (
  `category_id` bigint NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `category_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分类编码',
  `category_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分类名称',
  `budget_year` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '预算年度',
  `category_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分类类型：INCOME-收入预算，EXPENSE-支出预算，SPECIAL-专项预算',
  `parent_category_id` bigint NULL DEFAULT NULL COMMENT '上级分类ID',
  `parent_category_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '上级分类编码',
  `category_level` int NULL DEFAULT 1 COMMENT '层级',
  `is_stop` bigint NULL DEFAULT 0 COMMENT '是否停用：0-否，1-是',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`category_id`) USING BTREE,
  UNIQUE INDEX `category_code`(`category_code` ASC) USING BTREE,
  INDEX `idx_category_code`(`category_code` ASC) USING BTREE,
  INDEX `idx_category_type`(`category_type` ASC) USING BTREE,
  INDEX `idx_parent_category_id`(`parent_category_id` ASC) USING BTREE,
  INDEX `idx_budget_year`(`budget_year` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预算项目分类表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of budget_category
-- ----------------------------

-- ----------------------------
-- Table structure for budget_detail
-- ----------------------------
DROP TABLE IF EXISTS `budget_detail`;
CREATE TABLE `budget_detail`  (
  `detail_id` bigint NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `budget_year` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算年度',
  `subject_id` bigint NOT NULL COMMENT '预算主体ID',
  `subject_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算主体编码',
  `subject_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算主体名称',
  `item_id` bigint NOT NULL COMMENT '预算项目ID',
  `item_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算项目编码',
  `item_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算项目名称',
  `detail_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '明细类型：APPLY-申请占用，PAYOUT-报账执行',
  `amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '金额',
  `business_id` bigint NULL DEFAULT NULL COMMENT '业务ID',
  `business_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务单号（申请单号或报账单号等）',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '科室ID',
  `dept_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '科室编码',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '科室名称',
  `emp_id` bigint NULL DEFAULT NULL COMMENT '员工ID',
  `emp_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '员工工号',
  `emp_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '员工姓名',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`detail_id`) USING BTREE,
  INDEX `idx_subject_id`(`subject_id` ASC) USING BTREE,
  INDEX `idx_item_id`(`item_id` ASC) USING BTREE,
  INDEX `idx_detail_type`(`detail_type` ASC) USING BTREE,
  INDEX `idx_business_no`(`business_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 68 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预算明细表（记录预算的申请占用和执行明细）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of budget_detail
-- ----------------------------

-- ----------------------------
-- Table structure for budget_item
-- ----------------------------
DROP TABLE IF EXISTS `budget_item`;
CREATE TABLE `budget_item`  (
  `item_id` bigint NOT NULL AUTO_INCREMENT COMMENT '预算项目ID',
  `item_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '项目编码',
  `item_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '项目名称',
  `budget_year` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '预算年度',
  `category_id` bigint NOT NULL COMMENT '分类ID',
  `category_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类编码',
  `account_subject` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联会计科目',
  `is_centralized` bigint NULL DEFAULT 0 COMMENT '是否归口管理：0-否，1-是',
  `allow_adjust` bigint NULL DEFAULT 1 COMMENT '是否允许调整：0-否，1-是',
  `item_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '项目描述',
  `is_stop` bigint NULL DEFAULT 0 COMMENT '是否停用：0-否，1-是',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `category_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类类型：INCOME-收入预算，EXPENSE-支出预算',
  `parent_category_id` bigint NULL DEFAULT NULL COMMENT '上级分类ID（二级分类ID）',
  `parent_category_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '上级分类编码（二级分类编码）',
  PRIMARY KEY (`item_id`) USING BTREE,
  UNIQUE INDEX `item_code`(`item_code` ASC) USING BTREE,
  INDEX `idx_item_code`(`item_code` ASC) USING BTREE,
  INDEX `idx_category_id`(`category_id` ASC) USING BTREE,
  INDEX `idx_budget_year`(`budget_year` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 47 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预算项目表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of budget_item
-- ----------------------------

-- ----------------------------
-- Table structure for budget_item_subject
-- ----------------------------
DROP TABLE IF EXISTS `budget_item_subject`;
CREATE TABLE `budget_item_subject`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `item_id` bigint NOT NULL COMMENT '预算项目ID',
  `subject_id` bigint NOT NULL COMMENT '预算主体ID',
  `subject_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算主体编码',
  `subject_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预算主体名称',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_item_id`(`item_id` ASC) USING BTREE,
  INDEX `idx_subject_id`(`subject_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预算项目主体分配表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of budget_item_subject
-- ----------------------------

-- ----------------------------
-- Table structure for budget_subject
-- ----------------------------
DROP TABLE IF EXISTS `budget_subject`;
CREATE TABLE `budget_subject`  (
  `subject_id` bigint NOT NULL AUTO_INCREMENT COMMENT '预算主体ID',
  `subject_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预算主体编码',
  `subject_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预算主体名称',
  `subject_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '主体类型：CLINIC-临床科室，ADMIN-行政部门，TECH-医技科室',
  `manage_dept_id` bigint NULL DEFAULT NULL COMMENT '归口部门ID',
  `manage_dept_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '归口部门编码',
  `manage_dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '归口部门名称',
  `manage_emp_id` bigint NULL DEFAULT NULL COMMENT '归口负责人ID',
  `manage_emp_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '归口负责人工号',
  `manage_emp_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '归口负责人姓名',
  `is_stop` bigint NULL DEFAULT 0 COMMENT '是否停用：0-否，1-是',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`subject_id`) USING BTREE,
  UNIQUE INDEX `subject_code`(`subject_code` ASC) USING BTREE,
  INDEX `idx_subject_code`(`subject_code` ASC) USING BTREE,
  INDEX `idx_manage_dept_id`(`manage_dept_id` ASC) USING BTREE,
  INDEX `idx_manage_emp_id`(`manage_emp_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预算主体表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of budget_subject
-- ----------------------------

-- ----------------------------
-- Table structure for budget_subject_dept
-- ----------------------------
DROP TABLE IF EXISTS `budget_subject_dept`;
CREATE TABLE `budget_subject_dept`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '关联ID',
  `subject_id` bigint NOT NULL COMMENT '预算主体ID',
  `dept_id` bigint NOT NULL COMMENT '关联的科室ID',
  `dept_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联的科室编码',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联的科室名称',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_subject_id`(`subject_id` ASC) USING BTREE,
  INDEX `idx_dept_id`(`dept_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 67 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预算主体关联科室表（支持一个主体关联多个科室）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of budget_subject_dept
-- ----------------------------

-- ----------------------------
-- Table structure for business_apply
-- ----------------------------
DROP TABLE IF EXISTS `business_apply`;
CREATE TABLE `business_apply`  (
  `apply_id` bigint NOT NULL AUTO_INCREMENT COMMENT '申请ID',
  `apply_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请单号',
  `apply_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请类型：LEAVE-请假，ENTRY-入职，RESIGN-离职，OTHER-其他',
  `apply_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请标题',
  `applicant_id` bigint NOT NULL COMMENT '申请人ID',
  `applicant_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人工号',
  `applicant_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人姓名',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '部门ID',
  `leave_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '请假类型（仅请假申请）：ANNUAL-年假，SICK-病假，PERSONAL-事假等',
  `start_date` date NULL DEFAULT NULL COMMENT '开始日期',
  `end_date` date NULL DEFAULT NULL COMMENT '结束日期',
  `duration` int NULL DEFAULT 0 COMMENT '天数',
  `apply_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请事由',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'DRAFT' COMMENT '状态：DRAFT-草稿，PENDING-待审批，APPROVED-已审批，REJECTED-已拒绝，WITHDRAWN-已撤回',
  `process_instance_id` bigint NULL DEFAULT NULL COMMENT '流程实例ID',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`apply_id`) USING BTREE,
  UNIQUE INDEX `apply_no`(`apply_no` ASC) USING BTREE,
  INDEX `idx_apply_no`(`apply_no` ASC) USING BTREE,
  INDEX `idx_applicant_id`(`applicant_id` ASC) USING BTREE,
  INDEX `idx_apply_type`(`apply_type` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '业务申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of business_apply
-- ----------------------------

-- ----------------------------
-- Table structure for cost_cycle
-- ----------------------------
DROP TABLE IF EXISTS `cost_cycle`;
CREATE TABLE `cost_cycle`  (
  `cycle_id` bigint NOT NULL AUTO_INCREMENT COMMENT '周期ID（主键，自增，关联其他成本表）',
  `cycle_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '周期编码（唯一，格式：202510、2025Q3、2025）',
  `cycle_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '周期名称（用户易理解，如：2025年10月、2025年第三季度）',
  `cycle_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '周期类型（关联sys_code）',
  `start_date` date NOT NULL COMMENT '周期开始日期（如2025-10-01）',
  `end_date` date NOT NULL COMMENT '周期结束日期（如2025-10-31）',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态：1-启用，0-禁用（禁用历史周期，避免重复核算）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`cycle_id`) USING BTREE,
  UNIQUE INDEX `uk_cycle_code`(`cycle_code` ASC) USING BTREE COMMENT '周期编码唯一，避免重复创建同一周期',
  INDEX `idx_cycle_type`(`cycle_type` ASC) USING BTREE COMMENT '按周期类型筛选（如查询所有月度周期）'
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '成本核算周期配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of cost_cycle
-- ----------------------------

-- ----------------------------
-- Table structure for cost_main
-- ----------------------------
DROP TABLE IF EXISTS `cost_main`;
CREATE TABLE `cost_main`  (
  `cost_id` bigint NOT NULL AUTO_INCREMENT COMMENT '成本记录ID（主键，自增唯一标识）',
  `cost_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '成本单据编号（唯一，格式：COST+年月日+0001，便于追溯,自动生成）',
  `cycle_id` bigint NOT NULL COMMENT '核算周期ID（关联cost_cycle表，绑定成本所属周期）',
  `dept_id` bigint NOT NULL COMMENT '所属部门ID（关联sys_dept表，绑定成本归属部门）',
  `element_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '成本要素（关联sys_code的成本类型）',
  `cost_amount` decimal(16, 2) NOT NULL DEFAULT 0.00 COMMENT '成本金额（非负，保留2位小数，适配金额核算）',
  `occur_date` date NOT NULL COMMENT '成本实际发生日期（区别于录入日期，贴合实际业务）',
  `pay_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '付款方式（关联sys_code的付款方式）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注说明（如：采购打印纸、10月员工工资）',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '录入人ID（关联sys_emp表的emp_code，记录数据录入人）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '数据录入时间（自动生成，无需手动填写）',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '数据更新时间（修改时自动刷新）',
  PRIMARY KEY (`cost_id`) USING BTREE,
  UNIQUE INDEX `uk_cost_no`(`cost_no` ASC) USING BTREE COMMENT '唯一约束：成本单据编号不允许重复',
  INDEX `idx_cycle_dept`(`cycle_id` ASC, `dept_id` ASC) USING BTREE COMMENT '联合索引：提升按「周期+部门」查询的效率（台账查询核心）',
  INDEX `idx_element_type`(`element_type` ASC) USING BTREE COMMENT '单字段索引：提升按成本要素筛选的效率',
  INDEX `idx_occur_date`(`occur_date` ASC) USING BTREE COMMENT '单字段索引：提升按发生日期筛选的效率'
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '直接成本主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of cost_main
-- ----------------------------

-- ----------------------------
-- Table structure for ctrl_payout
-- ----------------------------
DROP TABLE IF EXISTS `ctrl_payout`;
CREATE TABLE `ctrl_payout`  (
  `payout_id` bigint NOT NULL AUTO_INCREMENT COMMENT '单号ID',
  `payout_billcode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '单号',
  `bill_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'APPLY' COMMENT '单据类型：APPLY-申请单，PAYOUT-报账单',
  `emp_id` bigint NOT NULL COMMENT '申请人ID',
  `emp_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人工号',
  `emp_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人姓名',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '部门ID',
  `is_nurse` bigint NULL DEFAULT 0 COMMENT '是否护士：0-否，1-是',
  `payout_type_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请类型',
  `apply_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '申请金额',
  `apply_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请事由',
  `apply_date` datetime NULL DEFAULT NULL COMMENT '申请日期',
  `source_apply_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源申请单号（关联申请单的payout_billcode）',
  `contract_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联合同编号',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'DRAFT' COMMENT '状态：DRAFT-草稿，PENDING-待审批，APPROVED-已审批，REJECTED-已拒绝，WITHDRAWN-已撤回',
  `template_config_id` bigint NULL DEFAULT NULL COMMENT '模板配置ID',
  `main_attach_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '主附件ID（用于附件关联）',
  `process_definition_id` bigint NULL DEFAULT NULL COMMENT '流程定义ID',
  `process_instance_id` bigint NULL DEFAULT NULL COMMENT '流程实例ID',
  `budget_id` bigint NULL DEFAULT NULL COMMENT '预算ID',
  `budget_item_id` bigint NULL DEFAULT NULL COMMENT '预算项目ID',
  `attachment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '附件路径（多个用逗号分隔）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`payout_id`) USING BTREE,
  UNIQUE INDEX `payout_billcode`(`payout_billcode` ASC) USING BTREE,
  INDEX `idx_apply_no`(`payout_billcode` ASC) USING BTREE,
  INDEX `idx_emp_id`(`emp_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_bill_type`(`bill_type` ASC) USING BTREE,
  INDEX `idx_process_instance_id`(`process_instance_id` ASC) USING BTREE,
  INDEX `idx_budget_id`(`budget_id` ASC) USING BTREE,
  INDEX `idx_template_config_id`(`template_config_id` ASC) USING BTREE,
  INDEX `idx_source_apply_no`(`source_apply_no` ASC) USING BTREE,
  INDEX `idx_contract_no`(`contract_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '报账表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ctrl_payout
-- ----------------------------

-- ----------------------------
-- Table structure for ctrl_payout_approval
-- ----------------------------
DROP TABLE IF EXISTS `ctrl_payout_approval`;
CREATE TABLE `ctrl_payout_approval`  (
  `approval_id` bigint NOT NULL AUTO_INCREMENT COMMENT '审批记录ID',
  `payout_id` bigint NOT NULL COMMENT '报账单ID',
  `approver_id` bigint NULL DEFAULT NULL COMMENT '审批人ID',
  `approver_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批人工号',
  `approver_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批人姓名',
  `approval_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批类型：APPROVE-通过，REJECT-驳回',
  `approval_opinion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批意见',
  `approval_time` datetime NULL DEFAULT NULL COMMENT '审批时间',
  `task_id` bigint NULL DEFAULT NULL COMMENT '流程任务ID',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务名称',
  `sort_order` int NULL DEFAULT 0 COMMENT '排序顺序',
  PRIMARY KEY (`approval_id`) USING BTREE,
  INDEX `idx_payout_id`(`payout_id` ASC) USING BTREE,
  INDEX `idx_approver_id`(`approver_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '审批记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ctrl_payout_approval
-- ----------------------------

-- ----------------------------
-- Table structure for ctrl_payout_detail
-- ----------------------------
DROP TABLE IF EXISTS `ctrl_payout_detail`;
CREATE TABLE `ctrl_payout_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `payout_id` bigint NOT NULL COMMENT '报账单ID',
  `item_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '项目名称',
  `item_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '项目类型',
  `amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '金额',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_payout_id`(`payout_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '报账明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ctrl_payout_detail
-- ----------------------------

-- ----------------------------
-- Table structure for ctrl_payout_invoice
-- ----------------------------
DROP TABLE IF EXISTS `ctrl_payout_invoice`;
CREATE TABLE `ctrl_payout_invoice`  (
  `invoice_id` bigint NOT NULL AUTO_INCREMENT COMMENT '发票ID',
  `payout_id` bigint NOT NULL COMMENT '报账单ID',
  `invoice_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发票代码',
  `invoice_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发票号码',
  `invoice_date` datetime NULL DEFAULT NULL COMMENT '发票日期',
  `invoice_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '发票金额',
  `invoice_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发票类型：VAT-增值税发票，COMMON-普通发票',
  `tax_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '税额',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`invoice_id`) USING BTREE,
  INDEX `idx_payout_id`(`payout_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '发票表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ctrl_payout_invoice
