-- ----------------------------
-- Table structure for ctrl_payout_payment
-- ----------------------------
DROP TABLE IF EXISTS `ctrl_payout_payment`;
CREATE TABLE `ctrl_payout_payment`  (
  `payment_id` bigint NOT NULL AUTO_INCREMENT COMMENT '支付清单ID',
  `payout_id` bigint NOT NULL COMMENT '报账单ID',
  `payment_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '支付金额',
  `payment_object` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '支付对象（收款人）',
  `payment_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '支付方式：BANK-银行转账，CASH-现金，CHECK-支票，OTHER-其他',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '银行名称',
  `bank_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '银行账号',
  `account_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '账户名称',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`payment_id`) USING BTREE,
  INDEX `idx_payout_id`(`payout_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '支付清单表' ROW_FORMAT = Dynamic;

