-- ----------------------------
-- Table structure for hr_apply
-- ----------------------------
DROP TABLE IF EXISTS `hr_apply`;
CREATE TABLE `hr_apply`  (
  `apply_id` bigint NOT NULL AUTO_INCREMENT COMMENT '申请ID',
  `apply_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请编码',
  `emp_id` bigint NOT NULL COMMENT '申请人员工编号（sys_emp的emp_id）',
  `emp_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人工号（冗余字段，方便查询）',
  `emp_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人姓名（冗余字段，方便查询）',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '申请人部门ID（冗余字段，方便查询）',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人部门名称（冗余字段，方便查询）',
  `emp_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人手机号（冗余字段，方便查询）',
  `hr_apply_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请类型（sys_code的HR_APPLY_TYPE查询）',
  `hr_apply_sub_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请子类型（sys_code的HR_APPLY_SUB_TYPE查询）',
  `start_time` datetime NULL DEFAULT NULL COMMENT '申请开始时间（请假起始/加班起始）',
  `end_time` datetime NULL DEFAULT NULL COMMENT '申请结束时间（请假结束/加班结束）',
  `supplement_id` bigint NULL DEFAULT NULL COMMENT '打卡记录编号',
  `apply_day` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请天数',
  `apply_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '申请事由',
  `main_attach_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '附件ID',
  `template_config_id` bigint NULL DEFAULT NULL COMMENT '模板配置ID',
  `process_definition_id` bigint NULL DEFAULT NULL COMMENT '流程定义ID',
  `process_instance_id` bigint NULL DEFAULT NULL COMMENT '流程实例ID',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '备注',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建人',
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '审批状态',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_nurse` bigint NULL DEFAULT NULL,
  PRIMARY KEY (`apply_id`) USING BTREE,
  INDEX `idx_emp_id`(`emp_id` ASC) USING BTREE COMMENT '员工索引',
  INDEX `idx_apply_no`(`apply_no` ASC) USING BTREE COMMENT '申请编码索引',
  INDEX `idx_status`(`status` ASC) USING BTREE COMMENT '状态索引',
  INDEX `idx_template_config_id`(`template_config_id` ASC) USING BTREE,
  INDEX `idx_process_instance_id`(`process_instance_id` ASC) USING BTREE,
  INDEX `idx_emp_code`(`emp_code` ASC) USING BTREE,
  INDEX `idx_dept_id`(`dept_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '补卡/请假/加班申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of hr_apply
-- ----------------------------

-- ----------------------------
-- Table structure for hr_att_ledger
-- ----------------------------
DROP TABLE IF EXISTS `hr_att_ledger`;
CREATE TABLE `hr_att_ledger`  (
  `ledger_id` bigint NOT NULL AUTO_INCREMENT COMMENT '台账编号（主键）',
  `emp_id` bigint NOT NULL COMMENT '员工编号',
  `att_month` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '考勤月份（格式：yyyy-MM，如2026-01）',
  `month_work_days` int NULL DEFAULT 0 COMMENT '本月工作日',
  `att_days` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '本月正常出勤天数',
  `leave_days` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '本月请假总天数',
  `overtime_days` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '本月加班总天数',
  `absent_days` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '本月旷工天数',
  `ledger_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'UNCALC' COMMENT '台账状态（sys_code: HR_LEDGER_STATUS）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ledger_id`) USING BTREE,
  UNIQUE INDEX `uk_emp_month`(`emp_id` ASC, `att_month` ASC) USING BTREE COMMENT '唯一索引，避免同一员工同一月份重复建台账',
  INDEX `idx_ledger_status`(`ledger_status` ASC) USING BTREE COMMENT '台账状态索引，优化薪酬计算查询'
) ENGINE = InnoDB AUTO_INCREMENT = 945 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '员工考勤台账表（月度汇总）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of hr_att_ledger
-- ----------------------------

-- ----------------------------
-- Table structure for hr_att_record
-- ----------------------------
DROP TABLE IF EXISTS `hr_att_record`;
CREATE TABLE `hr_att_record`  (
  `record_id` bigint NOT NULL AUTO_INCREMENT COMMENT '打卡记录编号（主键，自增）',
  `emp_id` bigint NOT NULL COMMENT '员工编号（关联员工信息表sys_emp的emp_id）',
  `att_date` date NOT NULL COMMENT '打卡日期（格式：yyyy-MM-dd）',
  `att_start_time` datetime NOT NULL COMMENT '打卡开始时间（格式：yyyy-MM-dd HH:mm:ss，记录精确打卡时刻）',
  `att_end_time` datetime NULL DEFAULT NULL COMMENT '打卡结束时间（格式：yyyy-MM-dd HH:mm:ss，记录精确打卡时刻）',
  `att_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'NORMAL' COMMENT '打卡状态（sys_code的HR_ATT_STATUS查出）',
  `is_supplement` tinyint(1) NULL DEFAULT 0 COMMENT '是否补卡（0：正常打卡，1：补卡）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '记录更新时间',
  `day` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `att_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `att_sub_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `apply_id` bigint NULL DEFAULT NULL COMMENT '申请ID（关联hr_apply表的apply_id）',
  PRIMARY KEY (`record_id`) USING BTREE,
  INDEX `idx_emp_date`(`emp_id` ASC, `att_date` ASC) USING BTREE COMMENT '员工+日期索引，优化个人考勤查询、台账汇总效率',
  INDEX `idx_att_status`(`att_status` ASC) USING BTREE COMMENT '打卡状态索引'
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '员工考勤记录表（原始打卡明细）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of hr_att_record
-- ----------------------------

-- ----------------------------
-- Table structure for hr_att_rule
-- ----------------------------
DROP TABLE IF EXISTS `hr_att_rule`;
CREATE TABLE `hr_att_rule`  (
  `rule_id` int NOT NULL AUTO_INCREMENT COMMENT '规则编号（主键）',
  `rule_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '规则类型（sys_code的RULE_TYPE查询）',
  `rule_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '规则名称（如病假扣薪、工作日加班加薪）',
  `sal_coefficient` decimal(5, 2) NOT NULL COMMENT '薪酬影响系数（0.8=病假发80%，1.5=加班1.5倍）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`rule_id`) USING BTREE,
  UNIQUE INDEX `uk_rule_type_name`(`rule_type` ASC, `rule_name` ASC) USING BTREE COMMENT '唯一索引，避免规则重复'
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '考勤规则配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of hr_att_rule
-- ----------------------------

-- ----------------------------
-- Table structure for hr_sal_calculate
-- ----------------------------
DROP TABLE IF EXISTS `hr_sal_calculate`;
CREATE TABLE `hr_sal_calculate`  (
  `calc_id` bigint NOT NULL AUTO_INCREMENT COMMENT '核算编号（主键）',
  `emp_id` bigint NOT NULL COMMENT '员工编号',
  `calc_month` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '核算月份（格式：yyyy-MM，与考勤台账一致）',
  `basic_salary` decimal(10, 2) NOT NULL COMMENT '基本工资（取自薪酬配置表）',
  `post_allowance` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '岗位津贴（取自薪酬配置表）',
  `overtime_salary` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '加班工资（考勤联动计算）',
  `leave_deduct` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '请假扣薪（考勤联动计算）',
  `absent_deduct` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '旷工扣罚（考勤联动计算）',
  `total_income` decimal(10, 2) NOT NULL COMMENT '应发工资（基本工资+津贴+加班工资-扣罚）',
  `social_security` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '个人社保代扣',
  `provident_fund` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '个人公积金代扣',
  `personal_tax` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '个人所得税',
  `net_salary` decimal(10, 2) NOT NULL COMMENT '实发工资（应发工资-代扣项-个税）',
  `calc_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'PENDING' COMMENT '核算状态（sys_code的CALC_STATUS查询）',
  `fail_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '核算失败原因（如无考勤台账、无薪酬配置）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`calc_id`) USING BTREE,
  UNIQUE INDEX `uk_emp_calc_month`(`emp_id` ASC, `calc_month` ASC) USING BTREE COMMENT '唯一索引，避免同一员工同一月份重复核算',
  INDEX `idx_calc_status`(`calc_status` ASC) USING BTREE COMMENT '核算状态索引，优化异常处理查询'
) ENGINE = InnoDB AUTO_INCREMENT = 237 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '薪酬核算表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of hr_sal_calculate
-- ----------------------------

-- ----------------------------
-- Table structure for hr_sal_config
-- ----------------------------
DROP TABLE IF EXISTS `hr_sal_config`;
CREATE TABLE `hr_sal_config`  (
  `config_id` int NOT NULL AUTO_INCREMENT COMMENT '配置编号（主键）',
  `emp_id` bigint NOT NULL COMMENT 'sys_emp（emp_id关联）',
  `basic_salary` decimal(10, 2) NULL DEFAULT NULL COMMENT '基本工资',
  `post_allowance` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '岗位津贴',
  `social_security` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '个人社保代扣比例',
  `provident_fund` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '个人公积金代扣比例',
  `tax_threshold` decimal(10, 2) NULL DEFAULT 5000.00 COMMENT '个税起征点',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'admin' COMMENT '创建人员工编码',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`config_id`) USING BTREE,
  UNIQUE INDEX `uk_emp_id`(`emp_id` ASC) USING BTREE COMMENT '唯一索引，每个员工只有一条薪酬配置'
) ENGINE = InnoDB AUTO_INCREMENT = 237 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '薪酬配置表（按员工配置）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of hr_sal_config
-- ----------------------------

-- ----------------------------
-- Table structure for pact_main
-- ----------------------------
DROP TABLE IF EXISTS `pact_main`;
CREATE TABLE `pact_main`  (
  `pact_id` bigint NOT NULL AUTO_INCREMENT COMMENT '合同ID',
  `contract_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '合同编号',
  `contract_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '合同名称',
  `contract_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '合同类型',
  `party_a` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '甲方',
  `party_b` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '乙方',
  `contract_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '合同金额',
  `sign_date` datetime NULL DEFAULT NULL COMMENT '签订日期',
  `start_date` datetime NULL DEFAULT NULL COMMENT '开始日期',
  `end_date` datetime NULL DEFAULT NULL COMMENT '结束日期',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'DRAFT' COMMENT '状态：DRAFT-草稿，PENDING-待审批，APPROVED-已审批，EXECUTING-执行中，ARCHIVED-已归档，REJECTED-已拒绝',
  `execution_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '执行状态：EXECUTING-履约中，COMPLETED-已履约，ARCHIVED-已归档',
  `is_manual_modify` tinyint(1) NULL DEFAULT 0 COMMENT '是否人工修改（0-否，1-是）',
  `template_config_id` bigint NULL DEFAULT NULL COMMENT '模板配置ID',
  `main_attach_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '主附件ID（用于附件关联）',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '负责部门ID',
  `emp_id` bigint NULL DEFAULT NULL COMMENT '申请人ID',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`pact_id`) USING BTREE,
  UNIQUE INDEX `contract_no`(`contract_no` ASC) USING BTREE,
  INDEX `idx_contract_no`(`contract_no` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_template_config_id`(`template_config_id` ASC) USING BTREE,
  INDEX `idx_emp_id`(`emp_id` ASC) USING BTREE,
  INDEX `idx_execution_status`(`execution_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '合同表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pact_main
-- ----------------------------

-- ----------------------------
-- Table structure for performance
-- ----------------------------
DROP TABLE IF EXISTS `performance`;
CREATE TABLE `performance`  (
  `performance_id` bigint NOT NULL AUTO_INCREMENT COMMENT '绩效ID',
  `performance_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '绩效编号',
  `emp_id` bigint NOT NULL COMMENT '职工ID',
  `emp_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '工号',
  `emp_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '姓名',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '部门ID',
  `performance_year` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '年度',
  `performance_quarter` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '季度：1-第一季度，2-第二季度，3-第三季度，4-第四季度',
  `performance_month` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '月份',
  `performance_score` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '绩效分数',
  `performance_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '绩效等级：EXCELLENT-优秀，GOOD-良好，QUALIFIED-合格，UNQUALIFIED-不合格',
  `performance_desc` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '绩效说明',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`performance_id`) USING BTREE,
  UNIQUE INDEX `performance_no`(`performance_no` ASC) USING BTREE,
  INDEX `idx_performance_no`(`performance_no` ASC) USING BTREE,
  INDEX `idx_emp_id`(`emp_id` ASC) USING BTREE,
  INDEX `idx_performance_year`(`performance_year` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '绩效表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of performance
-- ----------------------------

-- ----------------------------
-- Table structure for signature_info
-- ----------------------------
DROP TABLE IF EXISTS `signature_info`;
CREATE TABLE `signature_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `emp_id` bigint NOT NULL COMMENT '用户ID（关联用户表）',
  `emp_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '职工编码（工号）',
  `emp_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '职工姓名',
  `signature_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '签名文件名',
  `signature_blob` mediumblob NOT NULL COMMENT '签名图片二进制数据（MEDIUMBLOB支持最大16MB，足够存签名）',
  `file_size` int NULL DEFAULT NULL COMMENT '文件大小（字节），便于筛选',
  `file_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文件类型（png/jpg）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_emp_id`(`emp_id` ASC) USING BTREE COMMENT '职工ID索引，提升查询速度'
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '手写签名信息表（二进制存储）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of signature_info
-- ----------------------------

-- ----------------------------
-- Table structure for supplier
-- ----------------------------
DROP TABLE IF EXISTS `supplier`;
CREATE TABLE `supplier`  (
  `supplier_id` bigint NOT NULL AUTO_INCREMENT COMMENT '供应商ID',
  `supplier_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '供应商编码',
  `supplier_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '供应商名称',
  `contact_person` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系电话',
  `contact_email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系邮箱',
  `address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '地址',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '银行名称',
  `bank_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '银行账号',
  `account_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '账户名称',
  `tax_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '税号',
  `is_stop` bigint NULL DEFAULT 0 COMMENT '是否停用：0-启用，1-停用',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`supplier_id`) USING BTREE,
  UNIQUE INDEX `supplier_code`(`supplier_code` ASC) USING BTREE,
  INDEX `idx_supplier_code`(`supplier_code` ASC) USING BTREE,
  INDEX `idx_supplier_name`(`supplier_name` ASC) USING BTREE,
  INDEX `idx_is_stop`(`is_stop` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '供应商表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of supplier
-- ----------------------------

-- ----------------------------
-- Table structure for sys_attachment
-- ----------------------------
DROP TABLE IF EXISTS `sys_attachment`;
CREATE TABLE `sys_attachment`  (
  `attachment_id` bigint NOT NULL AUTO_INCREMENT COMMENT '附件ID',
  `business_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '业务类型：PAYOUT-报账，CONTRACT-合同，BUDGET_EXECUTION-预算执行，BUDGET_ADJUSTMENT-预算调整',
  `business_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务ID（允许NULL，用于临时附件；对于BUDGET_APPLY类型，存储apply_no申请单号）',
  `file_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件名称',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件路径',
  `file_size` bigint NULL DEFAULT NULL COMMENT '文件大小（字节）',
  `file_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文件类型（扩展名）',
  `upload_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '上传人',
  `upload_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`attachment_id`) USING BTREE,
  INDEX `idx_business`(`business_type` ASC, `business_id` ASC) USING BTREE,
  INDEX `idx_upload_user`(`upload_user` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 86 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '附件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sys_attachment
-- ----------------------------

-- ----------------------------
-- Table structure for sys_code
-- ----------------------------
DROP TABLE IF EXISTS `sys_code`;
CREATE TABLE `sys_code`  (
  `id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键ID',
  `code_value` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '字典值',
  `code_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '字典名称',
  `code_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '字典类型',
  `code_type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '字典类型名称',
  `is_stop` bigint NULL DEFAULT 0 COMMENT '是否停用：0-否，1-是',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_code_type`(`code_type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '字典表' ROW_FORMAT = Dynamic;

