-- Records of sys_position
-- ----------------------------

-- ----------------------------
-- Table structure for sys_position_user
-- ----------------------------
DROP TABLE IF EXISTS `sys_position_user`;
CREATE TABLE `sys_position_user`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `position_id` bigint NOT NULL COMMENT '岗位ID',
  `user_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户ID（UUID）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_position_user`(`position_id` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_position_id`(`position_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
