-- ----------------------------
-- Table structure for wf_process_definition
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_definition`;
CREATE TABLE `wf_process_definition`  (
  `definition_id` bigint NOT NULL AUTO_INCREMENT COMMENT '流程定义ID',
  `definition_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '流程定义KEY（如：PAYOUT_APPROVAL、CONTRACT_APPROVAL）',
  `definition_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '流程定义名称',
  `definition_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '流程类型：PAYOUT-报账审批，CONTRACT-合同审批',
  `business_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务类型值（如：MEAL-餐费，TRAVEL-差旅费等）',
  `process_xml` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '流程XML定义（BPMN格式）',
  `process_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '流程JSON定义（用于前端绘制）',
  `version` int NULL DEFAULT 1 COMMENT '版本号',
  `is_active` bigint NULL DEFAULT 1 COMMENT '是否启用：0-否，1-是',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '描述',
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`definition_id`) USING BTREE,
  UNIQUE INDEX `definition_key`(`definition_key` ASC) USING BTREE,
  INDEX `idx_definition_key`(`definition_key` ASC) USING BTREE,
  INDEX `idx_definition_type`(`definition_type` ASC) USING BTREE,
  INDEX `idx_is_active`(`is_active` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '流程定义表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wf_process_definition
-- ----------------------------

-- ----------------------------
-- Table structure for wf_process_task
-- ----------------------------
DROP TABLE IF EXISTS `wf_process_task`;
CREATE TABLE `wf_process_task`  (
  `task_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务ID (UUID)',
  `process_instance_id` bigint NULL DEFAULT NULL COMMENT '流程实例ID',
  `task_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务KEY（对于预算申请，就是apply_no）',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务名称',
  `next_task_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '下一节点任务ID (UUID)',
  `assignee_user_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '办理人ID',
  `assignee_user_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '办理人姓名',
  `assignee_emp_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '办理人工号',
  `assignee_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批人类型：user-指定用户，position-指定岗位，dept-部门负责人，manage_dept-归口审批人',
  `position_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '岗位代码（当 assigneeType = position 时使用）',
  `dept_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '部门代码（当 assigneeType = dept 时使用）',
  `candidate_users` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '候选办理人（JSON格式）',
  `task_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'PENDING' COMMENT '任务状态：PENDING-待办理，COMPLETED-已完成，TRANSFERRED-已转办',
  `task_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务类型：APPROVE-审批，REVIEW-审核',
  `approval_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批类型：SINGLE-单人审批，COUNTERSIGN-会签（全部同意），OR_SIGN-或签（任意一人同意）',
  `approver_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '审批人列表（JSON格式）',
  `approved_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '已审批人列表（JSON格式）',
  `need_print` int NULL DEFAULT 0 COMMENT '是否需要打印：0-否，1-是',
  `print_order` int NULL DEFAULT NULL COMMENT '打印顺序',
  `parent_task_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '父任务ID（用于加签场景，UUID）',
  `is_addsign_task` int NULL DEFAULT 0 COMMENT '是否为加签任务：0-否，1-是',
  `allow_addsign` int NULL DEFAULT 0 COMMENT '允许加签：0-否，1-是',
  `allow_transfer` int NULL DEFAULT 0 COMMENT '允许转办：0-否，1-是',
  `allow_reject` int NULL DEFAULT 0 COMMENT '允许退回：0-否，1-是',
  `allow_reduce_sign` int NULL DEFAULT 0 COMMENT '允许减签：0-否，1-是',
  `priority` int NULL DEFAULT 0 COMMENT '优先级',
  `due_date` datetime NULL DEFAULT NULL COMMENT '到期时间',
  `claim_time` datetime NULL DEFAULT NULL COMMENT '签收时间',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审批意见',
  `approver_signature` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '审批人手写签名（Base64图片数据）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `return_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '退回类型：RETURN_TO_CURRENT-退回后重新提交到本节点，RETURN_TO_START-退回后重新走流程',
  PRIMARY KEY (`task_id`) USING BTREE,
  INDEX `idx_process_instance_id`(`process_instance_id` ASC) USING BTREE,
  INDEX `idx_task_key`(`task_key` ASC) USING BTREE,
  INDEX `idx_assignee_user_id`(`assignee_user_id` ASC) USING BTREE,
  INDEX `idx_task_status`(`task_status` ASC) USING BTREE,
  INDEX `idx_next_task_id`(`next_task_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '流程任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wf_process_task
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
